  and id <> all (array['tq-sb-refresh-token-1', 'tq-sb-refresh-token-2', 'tq-sb-refresh-token-3', 'tq-sb-refresh-token-4', 'tq-sb-refresh-token-5']);

-- ===========================================================================
-- VALIDATION — fail loudly if this batch did not land exactly.
-- ===========================================================================
do $val$
declare
  v_topics int; v_lessons int; v_practice int; v_tests int; v_questions int; v_web boolean; v_mob boolean;
begin
  select count(*) into v_topics from public.learning_topics where source_kind = 'spring_boot_tutorial' and source_ref in ($sb227$security/spring-security-basics$sb227$, $sb228$security/authentication-vs-authorization$sb228$, $sb229$security/password-encoding-with-bcrypt$sb229$, $sb230$security/jwt-authentication$sb230$, $sb231$security/role-based-authorization$sb231$, $sb232$security/method-level-security$sb232$, $sb233$security/refresh-token$sb233$);
  if v_topics <> 7 then raise exception 'validation: expected 7 topics, found %', v_topics; end if;
  select count(*) filter (where c.metadata ->> 'block' = 'lesson'), count(*) filter (where c.metadata ->> 'block' = 'practice')
    into v_lessons, v_practice
    from public.learning_contents c join public.learning_topics t on t.id = c.topic_id
   where c.metadata ->> 'source' = 'spring_boot_seed' and t.source_kind = 'spring_boot_tutorial' and t.source_ref in ($sb227$security/spring-security-basics$sb227$, $sb228$security/authentication-vs-authorization$sb228$, $sb229$security/password-encoding-with-bcrypt$sb229$, $sb230$security/jwt-authentication$sb230$, $sb231$security/role-based-authorization$sb231$, $sb232$security/method-level-security$sb232$, $sb233$security/refresh-token$sb233$);
  if v_lessons <> 7 then raise exception 'validation: expected 7 lesson blocks, found %', v_lessons; end if;
  if v_practice <> 7 then raise exception 'validation: expected 7 practice blocks, found %', v_practice; end if;
  select count(*) into v_tests from public.practice_tests where id in ('pt-sb-spring-security-basics', 'pt-sb-authentication-vs-authorization', 'pt-sb-password-encoding-with-bcrypt', 'pt-sb-jwt-authentication', 'pt-sb-role-based-authorization', 'pt-sb-method-level-security', 'pt-sb-refresh-token') and learning_topic_id is not null;
  if v_tests <> 7 then raise exception 'validation: expected 7 linked mock tests, found %', v_tests; end if;
  select count(*) into v_questions from public.test_questions where test_id in ('pt-sb-spring-security-basics', 'pt-sb-authentication-vs-authorization', 'pt-sb-password-encoding-with-bcrypt', 'pt-sb-jwt-authentication', 'pt-sb-role-based-authorization', 'pt-sb-method-level-security', 'pt-sb-refresh-token');
  if v_questions <> 35 then raise exception 'validation: expected 35 MCQs, found %', v_questions; end if;
  select show_on_website, show_on_mobile into v_web, v_mob from (select id, show_on_website, show_on_mobile from public.learning_grids where lower(slug) = 'spring-boot-tutorial' and source_kind = 'seed' and source_ref = 'spring_boot_tutorial') g;
  raise notice '0134/106 OK: Spring Boot Tutorial batch 11: % topics, % lesson blocks, % practice blocks, % tests, % MCQs. Grid visible on website=%, mobile=%.',
    v_topics, v_lessons, v_practice, v_tests, v_questions, v_web, v_mob;
end
$val$;

notify pgrst, 'reload schema';
